import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.Cc8dJFaW.js";const u=JSON.parse('{"title":"2026-11-18 Agent 核心研究与竞品动态","description":"","frontmatter":{"title":"2026-11-18 Agent 核心研究与竞品动态","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-18.md","filePath":"zh/runtime/daily-intelligence/2026-11-18.md","lastUpdated":1795079081000}'),p={name:"zh/runtime/daily-intelligence/2026-11-18.md"};function n(i,a,l,h,s,d){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="_2026-11-18-agent-核心研究与竞品动态" tabindex="-1">2026-11-18 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-18-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-18 Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮核心判断：企业治理正在具体化为显式数据授权、按执行证据恢复、可重复评测和跨端审计。多Agent交付还需要区分子任务终态、结果消费和实际独立审阅。</p><p>实际起点：2026-11-18 10:05:23 Asia/Shanghai。最新main Registry为47人，88个仓库入口首轮264查询；基线接2026-11-17T024823Z，各来源旧缺口保留。下文日期用UTC。合入不等于打包发行；本轮实验、文章、开发派工均为0。</p><h2 id="事实观察" tabindex="-1">事实观察 <a class="header-anchor" href="#事实观察" aria-label="Permalink to &quot;事实观察&quot;">​</a></h2><p><span id="o1"></span></p><h3 id="o1-adk-mcp-参数不再自动读取会话状态" tabindex="-1">O1 ADK：MCP 参数不再自动读取会话状态 <a class="header-anchor" href="#o1-adk-mcp-参数不再自动读取会话状态" aria-label="Permalink to &quot;O1 ADK：MCP 参数不再自动读取会话状态&quot;">​</a></h3><p>11月17日已提交，破坏性安全变更。MCP 服务原来可通过声明参数名读取同名 session 字符串；现在仅接收开发者显式提供的 arguments，默认不发送。旧 prompt 参数需要迁移。这里是代码确认的边界修正，不能称已确认生产泄漏。</p><p><a href="https://github.com/google/adk-python/commit/889ddd3134df1dd1a626205ee78811950dec2a5c" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o2"></span></p><h3 id="o2-openhands-发送后504不应自动重跑" tabindex="-1">O2 OpenHands：发送后504不应自动重跑 <a class="header-anchor" href="#o2-openhands-发送后504不应自动重跑" aria-label="Permalink to &quot;O2 OpenHands：发送后504不应自动重跑&quot;">​</a></h3><p>11月17日 #6547 已合入。发送后504返回 X-Should-Retry:false 和 conversation ID；明确发送前超时才允许重试。原运行可能继续，手动无键重发仍可能重复。上游仍注明缺少同一默认客户端流程在 base/head 的完整对照；未跑需密钥的真实模型配方。</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/6547" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o3"></span></p><h3 id="o3-paperclip-准备失败恢复有执行前证据门槛" tabindex="-1">O3 Paperclip：准备失败恢复有执行前证据门槛 <a class="header-anchor" href="#o3-paperclip-准备失败恢复有执行前证据门槛" aria-label="Permalink to &quot;O3 Paperclip：准备失败恢复有执行前证据门槛&quot;">​</a></h3><p>11月18日 #22096 已合入。瞬时准备失败在工作区保存后进入原有有限重试通道；要求仍处准备阶段、无 provider 执行证据、租约释放与停止回执、工作区修复已核实。泛化 adapter_failed 继续等待人工。学习价值高，恢复治理竞争关注度提高。</p><p><a href="https://github.com/paperclipai/paperclip/pull/22096" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o4"></span></p><h3 id="o4-paperclip-给恢复控制器保留磁盘空间" tabindex="-1">O4 Paperclip：给恢复控制器保留磁盘空间 <a class="header-anchor" href="#o4-paperclip-给恢复控制器保留磁盘空间" aria-label="Permalink to &quot;O4 Paperclip：给恢复控制器保留磁盘空间&quot;">​</a></h3><p>11月17日 #22068 已合入。上游记录10GiB盘写满后7分钟83次重启失败；新机制预留控制器空间，恢复时释放，无法释放则用明确原因终止。数字来自上游事故，非本地实测。学习价值高，资源耗尽恢复进入重点雷达。</p><p><a href="https://github.com/paperclipai/paperclip/pull/22068" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o5"></span></p><h3 id="o5-paperclip-租约网络故障用结构化代码有限重试" tabindex="-1">O5 Paperclip：租约网络故障用结构化代码有限重试 <a class="header-anchor" href="#o5-paperclip-租约网络故障用结构化代码有限重试" aria-label="Permalink to &quot;O5 Paperclip：租约网络故障用结构化代码有限重试&quot;">​</a></h3><p>11月17日 #22087 已合入。Daytona SDK 吞掉 errno 的连接错误映射成闭集诊断 CONNECTION_FAILED，沿现有30/60秒预算重试并计入自动运行刹车；错误URL也会多等约90秒。学习价值高，恢复代价与重试边界清晰。</p><p><a href="https://github.com/paperclipai/paperclip/pull/22087" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o6"></span></p><h3 id="o6-paperclip-runner升级可以协商恢复旧状态" tabindex="-1">O6 Paperclip：Runner升级可以协商恢复旧状态 <a class="header-anchor" href="#o6-paperclip-runner升级可以协商恢复旧状态" aria-label="Permalink to &quot;O6 Paperclip：Runner升级可以协商恢复旧状态&quot;">​</a></h3><p>11月17日 #21976 已合入。提供方与Core协商可选能力，报告实际启动的 Runner 版本/构建；按其语义版本兼容规则接受停驻状态恢复，而非永远要求原digest。兼容判断是上游规则，不保证任意升级均可恢复。学习价值高，升级连续性值得体验。</p><p><a href="https://github.com/paperclipai/paperclip/pull/21976" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o7"></span></p><h3 id="o7-paperclip-重试键必须在模型可见schema中出现" tabindex="-1">O7 Paperclip：重试键必须在模型可见schema中出现 <a class="header-anchor" href="#o7-paperclip-重试键必须在模型可见schema中出现" aria-label="Permalink to &quot;O7 Paperclip：重试键必须在模型可见schema中出现&quot;">​</a></h3><p>11月17日 #22046 已合入。嵌套 allOf 在 Codex renderer 中隐藏 continuation 必填字段，改为等价直接条件，保留规范schema和校验；另避免已解决的账号修复被旧失败再次封锁。学习价值高，涉及模型可见契约与执行契约一致性。</p><p><a href="https://github.com/paperclipai/paperclip/pull/22046" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o8"></span></p><h3 id="o8-orca-重启后等待人的会话保持等待" tabindex="-1">O8 Orca：重启后等待人的会话保持等待 <a class="header-anchor" href="#o8-orca-重启后等待人的会话保持等待" aria-label="Permalink to &quot;O8 Orca：重启后等待人的会话保持等待&quot;">​</a></h3><p>11月17日 #43474 已合入。等待批准或回答的会话留在重启列表，不自动花一轮模型重新提问；旧批准请求已取消，用户续跑后产生新有效请求。学习价值高，恢复授权竞争关注度提高，第二圈位置保留。</p><p><a href="https://github.com/stablyai/orca/pull/43474" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o9"></span></p><h3 id="o9-orca-无法核实进程身份不等于身份不匹配" tabindex="-1">O9 Orca：无法核实进程身份不等于身份不匹配 <a class="header-anchor" href="#o9-orca-无法核实进程身份不等于身份不匹配" aria-label="Permalink to &quot;O9 Orca：无法核实进程身份不等于身份不匹配&quot;">​</a></h3><p>11月17日 #43707 已合入。无法读出身份的情况在9秒窗口退避重试，确认不匹配则立即结束；重启并发上限为 min(6,cores)。进程身份证明路径不适用于Windows，但并发上限适用。学习价值高，防止把瞬时观测失败当成授权失败。</p><p><a href="https://github.com/stablyai/orca/pull/43707" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o10"></span></p><h3 id="o10-orca-子agent结束不能结束根任务" tabindex="-1">O10 Orca：子Agent结束不能结束根任务 <a class="header-anchor" href="#o10-orca-子agent结束不能结束根任务" aria-label="Permalink to &quot;O10 Orca：子Agent结束不能结束根任务&quot;">​</a></h3><p>11月17日 #43672 已合入。Hermes 子Agent start/end 不再改变根会话完成状态；记住child身份，挡住延迟事件误关新turn。子工具事件只在根turn活跃时显示工作中。学习价值高，是多Agent状态适配的直接参照。</p><p><a href="https://github.com/stablyai/orca/pull/43672" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o11"></span></p><h3 id="o11-codex-断流恢复有预算和明确停止点" tabindex="-1">O11 Codex：断流恢复有预算和明确停止点 <a class="header-anchor" href="#o11-codex-断流恢复有预算和明确停止点" aria-label="Permalink to &quot;O11 Codex：断流恢复有预算和明确停止点&quot;">​</a></h3><p>11月18日 #62151 已合入。替换流按次数增加500ms等待，三次替换后报错并告知轨迹和草稿仍保留；连接稳定15秒或重置后清零。避免无限恢复循环，但并非执行副作用幂等方案。</p><p><a href="https://github.com/openai/codex/pull/62151" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o12"></span></p><h3 id="o12-codex-工具已接受但未再推理也要进入轨迹" tabindex="-1">O12 Codex：工具已接受但未再推理也要进入轨迹 <a class="header-anchor" href="#o12-codex-工具已接受但未再推理也要进入轨迹" aria-label="Permalink to &quot;O12 Codex：工具已接受但未再推理也要进入轨迹&quot;">​</a></h3><p>11月17日 #61973 已合入。保留已接受工具结果的顺序、身份和来源，即使之后没有模型请求；同文不同ID结果可区分，并记录本地上下文重置checkpoint。审计价值在记录已发生的接受，不仅记录模型看过的内容。</p><p><a href="https://github.com/openai/codex/pull/61973" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o13"></span></p><h3 id="o13-codex-委派继承发起turn的成本归属" tabindex="-1">O13 Codex：委派继承发起turn的成本归属 <a class="header-anchor" href="#o13-codex-委派继承发起turn的成本归属" aria-label="Permalink to &quot;O13 Codex：委派继承发起turn的成本归属&quot;">​</a></h3><p>11月17日 #62072 已合入。子孙Agent继承发起turn的cost_center等快照，父任务后续改值不追溯污染；排除特定覆盖与请求元数据，保留子线程自身ID。归属传播不等于授权委派。</p><p><a href="https://github.com/openai/codex/pull/62072" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o14"></span></p><h3 id="o14-codex-撤回昨日ssh系统目录特殊遮罩" tabindex="-1">O14 Codex：撤回昨日SSH系统目录特殊遮罩 <a class="header-anchor" href="#o14-codex-撤回昨日ssh系统目录特殊遮罩" aria-label="Permalink to &quot;O14 Codex：撤回昨日SSH系统目录特殊遮罩&quot;">​</a></h3><p>11月17日 #62058 已合入，取消 /etc/ssh/ssh_config.d 的空只读覆盖，改为服从配置的文件系统策略，并移除相关文档和测试夹具。因此昨日O43的具体遮罩机制已被后续修订，不能继续当成当前稳定设计。</p><p><a href="https://github.com/openai/codex/pull/62058" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o15"></span></p><h3 id="o15-codex-windows沙箱服务控制收紧" tabindex="-1">O15 Codex：Windows沙箱服务控制收紧 <a class="header-anchor" href="#o15-codex-windows沙箱服务控制收紧" aria-label="Permalink to &quot;O15 Codex：Windows沙箱服务控制收紧&quot;">​</a></h3><p>11月17日 #62122 已合入。SYSTEM与提升权限管理员有完整控制，普通已认证用户只获查询/启动等有限权限；ACL应用失败则启动失败。主干状态不等于所有Windows安装包已经更新。</p><p><a href="https://github.com/openai/codex/pull/62122" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o16"></span></p><h3 id="o16-codex-子agent状态和轨迹进入tui" tabindex="-1">O16 Codex：子Agent状态和轨迹进入TUI <a class="header-anchor" href="#o16-codex-子agent状态和轨迹进入tui" aria-label="Permalink to &quot;O16 Codex：子Agent状态和轨迹进入TUI&quot;">​</a></h3><p>11月18日 #62149、62157、62159 已合入。可查看spawn树和子会话；完成/停止/失败状态保留，实时通知优先于迟到发现结果。价值是可追溯协作，不仅新增一个侧栏入口。</p><p><a href="https://github.com/openai/codex/pull/62149" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o17"></span></p><h3 id="o17-codex-续跑与分叉先检查远端冲突" tabindex="-1">O17 Codex：续跑与分叉先检查远端冲突 <a class="header-anchor" href="#o17-codex-续跑与分叉先检查远端冲突" aria-label="Permalink to &quot;O17 Codex：续跑与分叉先检查远端冲突&quot;">​</a></h3><p>11月17日 #62065 已合入。根参数与子命令的remote冲突在读取认证token前报错，减少续跑绑定到错误后端的歧义。它是适配/连接边界检查，不是FCoP路由规范。</p><p><a href="https://github.com/openai/codex/pull/62065" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o18"></span></p><h3 id="o18-agents-python-0-25-发行包含接入与迁移变化" tabindex="-1">O18 Agents Python 0.25：发行包含接入与迁移变化 <a class="header-anchor" href="#o18-agents-python-0-25-发行包含接入与迁移变化" aria-label="Permalink to &quot;O18 Agents Python 0.25：发行包含接入与迁移变化&quot;">​</a></h3><p>11月18日UTC已发行v0.25.0，发布记录标11月17日。包含第三方session适配工具、可选handoff错误恢复、MCP v2并发HTTP请求，并移除Runloop沙箱provider。安装升级前应核对提供方依赖，不把全部历史合入重复算新增。</p><p><a href="https://github.com/openai/openai-agents-python/releases/tag/v0.25.0" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o19"></span></p><h3 id="o19-agents-python-记忆时间比较统一到utc" tabindex="-1">O19 Agents Python：记忆时间比较统一到UTC <a class="header-anchor" href="#o19-agents-python-记忆时间比较统一到utc" aria-label="Permalink to &quot;O19 Agents Python：记忆时间比较统一到UTC&quot;">​</a></h3><p>11月18日 #6066 已合入。记忆合并遇到不同UTC offset和数量上限时可能选旧轨迹；现在按UTC比较并保留小数秒，兼容已有raw memories。这是选择正确性，不等于跨用户隔离改进。</p><p><a href="https://github.com/openai/openai-agents-python/pull/6066" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o20"></span></p><h3 id="o20-agents-js-昨日审批续跑提案现已合入" tabindex="-1">O20 Agents JS：昨日审批续跑提案现已合入 <a class="header-anchor" href="#o20-agents-js-昨日审批续跑提案现已合入" aria-label="Permalink to &quot;O20 Agents JS：昨日审批续跑提案现已合入&quot;">​</a></h3><p>11月17日 #2673 已合入，更新昨日O13的OPEN状态。续跑按原始调用顺序使用同响应已完成工具结果，仅新完成结果发事件/写Session，校验恢复回执。仍未据此宣称新npm版本发行。</p><p><a href="https://github.com/openai/openai-agents-js/pull/2673" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o21"></span></p><h3 id="o21-claude-code-2-1-327-凭证入口与恢复诊断" tabindex="-1">O21 Claude Code 2.1.327：凭证入口与恢复诊断 <a class="header-anchor" href="#o21-claude-code-2-1-327-凭证入口与恢复诊断" aria-label="Permalink to &quot;O21 Claude Code 2.1.327：凭证入口与恢复诊断&quot;">​</a></h3><p>11月17日正式发行。MCP JSON可从stdin读取以避免token出现在命令行；显示失效权限/沙箱/hook等配置问题。修复Remote Control停止worktree服务器误删运行会话git-ignored文件。发行说明为上游证据，未本机复现。</p><p><a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.327" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o22"></span></p><h3 id="o22-langfuse-4-82-审计读路径切换与组织边界" tabindex="-1">O22 Langfuse 4.82：审计读路径切换与组织边界 <a class="header-anchor" href="#o22-langfuse-4-82-审计读路径切换与组织边界" aria-label="Permalink to &quot;O22 Langfuse 4.82：审计读路径切换与组织边界&quot;">​</a></h3><p>11月17日 #20045 合入并包含在4.82发行。审计从ClickHouse读取，记录Event/Outcome；项目转组织后新组织仅见迁移后的事件，列表与导出字段不同，重复行可能在后台合并前暂时出现。昨日批量删除审计也明确进入本发行。</p><p><a href="https://github.com/langfuse/langfuse/pull/20045" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o23"></span></p><h3 id="o23-copilot-审计进入agent-365控制面" tabindex="-1">O23 Copilot：审计进入Agent 365控制面 <a class="header-anchor" href="#o23-copilot-审计进入agent-365控制面" aria-label="Permalink to &quot;O23 Copilot：审计进入Agent 365控制面&quot;">​</a></h3><p>11月17日官方宣布可将跨Copilot客户端的会话、提示、响应和工具活动流入Agent 365，关联Purview/Defender风险信息。限GitHub Enterprise Cloud的EMU客户。企业治理与集成竞争关注度高；可见活动不等于动作前统一拦截。</p><p><a href="https://github.blog/changelog/2026-11-17-monitor-github-copilot-activity-through-microsoft-agent-365/" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o24"></span></p><h3 id="o24-copilot-entra登录公开预览" tabindex="-1">O24 Copilot：Entra登录公开预览 <a class="header-anchor" href="#o24-copilot-entra登录公开预览" aria-label="Permalink to &quot;O24 Copilot：Entra登录公开预览&quot;">​</a></h3><p>11月17日公开预览，CLI需1.0.113+，当前Windows/macOS，Linux待后续。OIDC EMU SSO与Microsoft365推理/许可是不同路径，受不同计划和组织策略管理。身份与计费边界学习价值高，非通用免配置登录。</p><p><a href="https://github.blog/changelog/2026-11-17-github-copilot-cli-adds-microsoft-entra-sign-in-as-a-preview/" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o25"></span></p><h3 id="o25-copilot-evals-定制员工能力有重复评测入口" tabindex="-1">O25 Copilot Evals：定制员工能力有重复评测入口 <a class="header-anchor" href="#o25-copilot-evals-定制员工能力有重复评测入口" aria-label="Permalink to &quot;O25 Copilot Evals：定制员工能力有重复评测入口&quot;">​</a></h3><p>11月17日公开预览。可对skill/custom agent/MCP设计任务和检查，比较修改前后，每次运行需批准，底层使用本地Vally引擎。支持VSCode、CLI和App入口。体验价值高，尚未安装，不能把产品宣称当成可靠性已证明。</p><p><a href="https://github.blog/changelog/2026-11-17-github-copilot-evals-is-now-in-public-preview/" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o26"></span></p><h3 id="o26-github-event-streams-等待事件再唤醒" tabindex="-1">O26 GitHub Event Streams：等待事件再唤醒 <a class="header-anchor" href="#o26-github-event-streams-等待事件再唤醒" aria-label="Permalink to &quot;O26 GitHub Event Streams：等待事件再唤醒&quot;">​</a></h3><p>11月17日预览，需候补批准。保持连接订阅PR评审、提交、合并关闭和检查事件，无需公网webhook接收器。对长驻员工的事件适配有研究价值；尚未核实重放、断线补漏、顺序或exactly-once语义，不是FCoP同层替代。</p><p><a href="https://github.blog/changelog/2026-11-17-github-event-streams-is-now-in-preview/" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o27"></span></p><h3 id="o27-copilot审查-按风险选深度并显示选择" tabindex="-1">O27 Copilot审查：按风险选深度并显示选择 <a class="header-anchor" href="#o27-copilot审查-按风险选深度并显示选择" aria-label="Permalink to &quot;O27 Copilot审查：按风险选深度并显示选择&quot;">​</a></h3><p>11月17日Adaptive、公开仓库跨库上下文和secret检测进入公开预览；Balanced仍默认，Adaptive不得超过组织最大深度。Azure Repos审查GA。学习价值在审阅成本/风险与可解释选择，未独立验证检测效果。</p><p><a href="https://github.blog/changelog/2026-11-17-copilot-code-review-adaptive-effort-secret-detection-and-more/" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o28"></span></p><h3 id="o28-copilot-app-已登录浏览器成为执行端" tabindex="-1">O28 Copilot App：已登录浏览器成为执行端 <a class="header-anchor" href="#o28-copilot-app-已登录浏览器成为执行端" aria-label="Permalink to &quot;O28 Copilot App：已登录浏览器成为执行端&quot;">​</a></h3><p>11月17日浏览器操作公开预览，Chromium扩展、隔离tab组，默认关闭并需启用Computer/Browser Use。Azure DevOps接入也是预览、无Cloud sessions；GHES GA是此前事件，今天公告只作边界补充，不重复算新GA。产品竞争风险高，重点看身份和敏感动作批准。</p><p><a href="https://github.blog/changelog/2026-11-17-github-copilot-app-microsoft-ignite-releases/" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o29"></span></p><h3 id="o29-eigent-1-0-8-会话工作日志与就地审批" tabindex="-1">O29 Eigent 1.0.8：会话工作日志与就地审批 <a class="header-anchor" href="#o29-eigent-1-0-8-会话工作日志与就地审批" aria-label="Permalink to &quot;O29 Eigent 1.0.8：会话工作日志与就地审批&quot;">​</a></h3><p>11月17日正式发行。新的会话时间线默认展示工作日志，审批/提问定位到文件或命令，并标记模型变化；全局搜索覆盖任务、文件、Automations等。普通视觉改动不单列，收录交付可观测性。学习价值中高、产品压力中高；未安装验收，雷达圈层不改。</p><p><a href="https://github.com/eigent-ai/eigent/releases/tag/v1.0.8" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o30"></span></p><h3 id="o30-onward-windows更新器采用校验与目录切换" tabindex="-1">O30 Onward：Windows更新器采用校验与目录切换 <a class="header-anchor" href="#o30-onward-windows更新器采用校验与目录切换" aria-label="Permalink to &quot;O30 Onward：Windows更新器采用校验与目录切换&quot;">​</a></h3><p>11月17日daily build v2.1.0-daily.20261117.1 已发布，非稳定版声明。更新在后台下载、校验、解包，由无窗口helper切换安装目录。学习价值高，Windows交付纳入专项观察；签名、失败回滚和实机升级仍未核验。</p><p><a href="https://github.com/OPPO-PersonalAI/Onward-Agent-Workbench/releases/tag/v2.1.0-daily.20261117.1" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o31"></span></p><h3 id="o31-beads-候选版明确单向数据迁移" tabindex="-1">O31 Beads：候选版明确单向数据迁移 <a class="header-anchor" href="#o31-beads-候选版明确单向数据迁移" aria-label="Permalink to &quot;O31 Beads：候选版明确单向数据迁移&quot;">​</a></h3><p>11月17日v1.4.0-rc.3预发行，常规安装渠道仍给稳定版。旧库迁到schema74后旧二进制拒绝读取，回退要恢复备份；rc.1/2到rc.3本身无需新迁移。多平台二进制不等于所有平台实测。学习价值高，迁移成本明确。</p><p><a href="https://github.com/gastownhall/beads/releases/tag/v1.4.0-rc.3" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o32"></span></p><h3 id="o32-agentlas-跨agent事实与单agent偏好分开" tabindex="-1">O32 Agentlas：跨Agent事实与单Agent偏好分开 <a class="header-anchor" href="#o32-agentlas-跨agent事实与单agent偏好分开" aria-label="Permalink to &quot;O32 Agentlas：跨Agent事实与单Agent偏好分开&quot;">​</a></h3><p>11月17日稳定渠道os-v1.2.99发行。个人生活/时间意愿作为各Agent共享fact，preference只表达单Agent回答方式；旧记录不自动重标。boundary字段engine接受但不存，由desktop保存。学习价值中高，跨端记忆持久化需验证，不能仅凭schema称完整支持。</p><p><a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.99" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o33"></span></p><h3 id="o33-赵越agent-config-指定审阅者与实际派发分开" tabindex="-1">O33 赵越agent-config：指定审阅者与实际派发分开 <a class="header-anchor" href="#o33-赵越agent-config-指定审阅者与实际派发分开" aria-label="Permalink to &quot;O33 赵越agent-config：指定审阅者与实际派发分开&quot;">​</a></h3><p>11月17日已提交。上游记录配置both却连续三轮只派Codex；规则现在要求先声明解析出的审阅者再按集合派发，去掉相互冲突的第二套选择规则。实际派发与期望集合的自动比对仍留待后续。上游两轮评审不是本地实验。</p><p><a href="https://github.com/yzhao062/agent-config/commit/ee57b98eb93df6b820b4e92376a015ef7aef8414" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o34"></span></p><h3 id="o34-browser-use-撤回过度的secret隔离描述" tabindex="-1">O34 Browser Use：撤回过度的secret隔离描述 <a class="header-anchor" href="#o34-browser-use-撤回过度的secret隔离描述" aria-label="Permalink to &quot;O34 Browser Use：撤回过度的secret隔离描述&quot;">​</a></h3><p>11月17日README已修订：vault与域范围凭证不进入prompt/task文本，但模型生成的Python仍可读取secret值，因此删除“Agent看不见凭证”的泛化表达。是能力边界澄清，不是已发行的隔离修复。</p><p><a href="https://github.com/browser-use/browser-use/commit/e9337176a22aacfb5e514c7755f1904e789982d9" target="_blank" rel="noreferrer">原始证据</a></p><p><span id="o35"></span></p><h3 id="o35-adk-技能更新放到实际脚本执行时" tabindex="-1">O35 ADK：技能更新放到实际脚本执行时 <a class="header-anchor" href="#o35-adk-技能更新放到实际脚本执行时" aria-label="Permalink to &quot;O35 ADK：技能更新放到实际脚本执行时&quot;">​</a></h3><p>11月17日已提交。删除构造模型请求时写沙箱的路径，改由实际运行脚本时刷新对应环境的旧副本。启用revalidate_skills时，执行前直接读环境文件仍可能看到旧版本。多会话环境与生效版本值得研究，不能称即时全量同步。</p><p><a href="https://github.com/google/adk-python/commit/5f2f2279c9a29c473efb4dec151ba4b53e841cd9" target="_blank" rel="noreferrer">原始证据</a></p><h2 id="研究分析" tabindex="-1">研究分析 <a class="header-anchor" href="#研究分析" aria-label="Permalink to &quot;研究分析&quot;">​</a></h2><h3 id="a1-恢复研究应先判定是否已经执行" tabindex="-1">A1 恢复研究应先判定是否已经执行 <a class="header-anchor" href="#a1-恢复研究应先判定是否已经执行" aria-label="Permalink to &quot;A1 恢复研究应先判定是否已经执行&quot;">​</a></h3><p><a href="#o2">O2</a> · <a href="#o3">O3</a> · <a href="#o4">O4</a> · <a href="#o5">O5</a> · <a href="#o8">O8</a> · <a href="#o9">O9</a> · <a href="#o11">O11</a></p><p>已有证据：OpenHands避免发送后重试，Paperclip只在执行前证据充分时续跑，Orca把等待人和正在工作分开。待验证：CodeFlowMu重启后的任务是否保留这种区分。实验候选：分别注入发送前/后超时、满盘和审批等待重启，统计重复动作、人工等待、恢复时延；不预报通过。FCoP比较状态/回执/证据，重试预算、租约和磁盘预留归Runtime。代价是故障注入与未知状态处理。互动：结果未知时，哪些证据足以安全接替？</p><h3 id="a2-企业治理向身份、审计和可执行评测延伸" tabindex="-1">A2 企业治理向身份、审计和可执行评测延伸 <a class="header-anchor" href="#a2-企业治理向身份、审计和可执行评测延伸" aria-label="Permalink to &quot;A2 企业治理向身份、审计和可执行评测延伸&quot;">​</a></h3><p><a href="#o1">O1</a> · <a href="#o15">O15</a> · <a href="#o21">O21</a> · <a href="#o23">O23</a> · <a href="#o24">O24</a> · <a href="#o25">O25</a> · <a href="#o27">O27</a> · <a href="#o28">O28</a> · <a href="#o34">O34</a></p><p>已有证据：Agent365集中观测、Entra身份、Evals回归和MCP显式参数分别解决不同层次；浏览器接入扩大已登录身份的可用范围。待验证：这些能力能否组成动作前后闭环，当前公告不能证明。体验候选为Copilot Evals，先核对许可、安装源、运行批准与本地数据范围。CodeFlowMu岗位身份、组织凭证与审计要分层对照；不是FCoP内核统一认证需求。代价为企业许可、账号配置、隐私与模型成本。互动：评测能否检查未发生的敏感副作用？</p><h3 id="a3-委派结果、根任务状态和独立审阅需要不同证据" tabindex="-1">A3 委派结果、根任务状态和独立审阅需要不同证据 <a class="header-anchor" href="#a3-委派结果、根任务状态和独立审阅需要不同证据" aria-label="Permalink to &quot;A3 委派结果、根任务状态和独立审阅需要不同证据&quot;">​</a></h3><p><a href="#o7">O7</a> · <a href="#o10">O10</a> · <a href="#o12">O12</a> · <a href="#o13">O13</a> · <a href="#o16">O16</a> · <a href="#o20">O20</a> · <a href="#o29">O29</a> · <a href="#o33">O33</a></p><p>已有证据：子完成信号曾误关根任务，指定审阅者也可能未真正派发，已接受结果可能从未进入模型。待验证：本地三岗位工作流是否存在同类缺口。实验候选：研究→汇总→独立复核，注入迟到child结束、同文不同ID结果、父turn改变和审批恢复；比较请求集合、实际派发、成果消费与验收。FCoP可比较任务/工件/来源契约，成本归属继承不等于权限继承。代价是持久化关联ID与额外验收步骤。互动：如何证明独立复核真的发生？</p><h3 id="a4-协议观察-事件唤醒属于互补接入层" tabindex="-1">A4 协议观察：事件唤醒属于互补接入层 <a class="header-anchor" href="#a4-协议观察-事件唤醒属于互补接入层" aria-label="Permalink to &quot;A4 协议观察：事件唤醒属于互补接入层&quot;">​</a></h3><p><a href="#o6">O6</a> · <a href="#o7">O7</a> · <a href="#o17">O17</a> · <a href="#o26">O26</a> · <a href="#o31">O31</a> · <a href="#o35">O35</a></p><p>已有证据：GitHub事件订阅、Runner恢复协商、模型可见schema和技能实际版本各有自己的契约。Event Streams是外部事件源，不是文件/工件式协作的同层替代。待验证：断线补漏、重复事件、版本协商和schema渲染是否保持业务语义。实验候选是离线重放重复/乱序/断线事件，观察任务是否只消费一次且保留缺口，不声称上游exactly-once。代价为适配层持久化、补偿和迁移。Beads候选版仅在备份副本上体验。</p><h3 id="a5-竞品学习重点是持续交付和可维护安装" tabindex="-1">A5 竞品学习重点是持续交付和可维护安装 <a class="header-anchor" href="#a5-竞品学习重点是持续交付和可维护安装" aria-label="Permalink to &quot;A5 竞品学习重点是持续交付和可维护安装&quot;">​</a></h3><p><a href="#o3">O3</a> · <a href="#o4">O4</a> · <a href="#o5">O5</a> · <a href="#o6">O6</a> · <a href="#o8">O8</a> · <a href="#o9">O9</a> · <a href="#o10">O10</a> · <a href="#o28">O28</a> · <a href="#o29">O29</a> · <a href="#o30">O30</a> · <a href="#o31">O31</a> · <a href="#o32">O32</a></p><p>判断：Paperclip恢复与升级连续性、Orca人工等待/根子状态、Eigent工作证据、Onward更新交付、Agentlas共享记忆边界值得分别研究；这些事实不证明整体成熟。优先体验Paperclip恢复故障与Orca审批重启，Eigent随后验证一份完整成果的日志/批准可追溯性，Onward需Windows更新与回滚实机证据。学习价值高，产品与治理风险持续关注；不改雷达圈层。全部未安装实测，License/商业边界本轮未全量重审，沿用条目仅作线索，体验前必须重新核对。安装、依赖、凭证、回滚属于Runtime/产品层。</p><h2 id="跨项目共振、分类和双源核查" tabindex="-1">跨项目共振、分类和双源核查 <a class="header-anchor" href="#跨项目共振、分类和双源核查" aria-label="Permalink to &quot;跨项目共振、分类和双源核查&quot;">​</a></h2><p>A1/A3是恢复与协作实验候选，A2是企业治理体验候选，A4是互补协议资料及实验候选，A5是竞品体验顺序。均未执行，不自动进入产品开发。</p><p>GitHub首轮逐仓库查询commits、Issues/PR和Release，并深读入选PR/commit。满页未完成仍记partial；TSA三个API404，原Superset迁移入口旧缺口保留，不能称停运或无变化。未穷尽Discussion、架构、安装和License，也没有完成47人全部社交帖/回复。非GitHub实际打开Cursor changelog、MCP博客、赵越主页、GitHub changelog及六篇11月17日官方公告；前两者当前最新日期仍为11月6日/11日，未当成当日新增。GitHub两个链接不算两种来源。治理六人关系保持原边界，Mansura项目不是AGENTSAFE官方Artifact；机器人不代替作者参与证据。</p><p>已读取昨日发布报告去重；O14更新昨日O43，O20更新昨日O13，O22新增发行与读路径状态，GHES已有GA不重复计新事件。新模型名称/营销、小版本无内容和普通UI改动未单列。CodeFlowMu/FCoP关联未经本地实验，均为待验证研究判断。</p><p>日档仅四个允许源文件，保留主页入口、布局、公开快照；未改research/runtime/**和其他业务生命周期。发布与线上验收结果以本地回执及聊天为准，本文不提前声称成功。未发外部评论。</p><h2 id="_11-月-19-日补记-承接-11-月-17-日未完成实验" tabindex="-1">11 月 19 日补记：承接 11 月 17 日未完成实验 <a class="header-anchor" href="#_11-月-19-日补记-承接-11-月-17-日未完成实验" aria-label="Permalink to &quot;11 月 19 日补记：承接 11 月 17 日未完成实验&quot;">​</a></h2><p><a href="./2026-11-17#11-月-17-日研究续报">11 月 17 日续报</a>列出的两项待办在本日研究中没有执行，也没有作为跨日待办列出。这是研究跟踪遗漏；本日重新编号的 A2、A4 是不同议题，不能视为旧项已承接。</p><table tabindex="0"><thead><tr><th>11 月 17 日遗留实验</th><th>截至 11 月 18 日的状态</th><th>下一步验证</th></tr></thead><tbody><tr><td>A2：Stop／超时后的副作用与停止结算</td><td>未实验</td><td>在停止发生于 dispatch 前、dispatch 后及回执丢失三处注入中断，核对真实副作用、停止回执与恢复判定</td></tr><tr><td>A4：子结果进入父任务并被正式验收</td><td>仅做过根任务验收投影对照；完整父子消费未实验</td><td>用父任务、多个子结果和独立验收者，核对结果是否进入正确父任务与工件版本、是否被消费和验收</td></tr></tbody></table><p>本补记于 11 月 19 日作出，不追记为 18 日已经完成的实验或成果。结论仍为两项待验证，不生成文章或开发评审。</p>',169)])])}const b=e(p,[["render",n]]);export{u as __pageData,b as default};
